INSERT INTO glossary_terms (id, term, slug, definition, status) VALUES
('glo-aaron-sumo-sacerdote', 'Aarón (sumo sacerdote)', 'aaron-sumo-sacerdote', 'Aarón fue hermano de Moisés, levita y colaborador suyo durante el éxodo. En la narrativa bíblica fue consagrado para ejercer el sacerdocio y aparece como el primer sumo sacerdote de Israel, con funciones representativas y cultuales vinculadas al tabernáculo.', 'Publicado básico'),
('glo-abdias-mayordomo-acab', 'Abdías (mayordomo de Acab)', 'abdias-mayordomo-acab', 'Abdías fue el funcionario encargado de la casa o palacio del rey Acab. El relato destaca que temía profundamente a Jehová y que, durante la persecución promovida por Jezabel, escondió a cien profetas de Jehová en cuevas y los sostuvo con pan y agua. Más tarde, durante la gran sequía, encontró a Elías y llevó a Acab el aviso de que el profeta estaba presente.', 'Publicado básico'),
('glo-abdias-profeta-libro', 'Abdías (profeta del libro de Abdías)', 'abdias-profeta-libro', 'Abdías es el profeta identificado por nombre en la apertura del libro que lleva su nombre, una breve profecía dirigida principalmente contra Edom. El texto condena la violencia y la complacencia de Edom ante la calamidad de Jerusalén y anuncia juicio sobre Edom, restauración para Sion y el dominio final de YHWH.', 'Publicado básico'),
('glo-abel', 'Abel', 'abel', 'Abel fue hijo de Adán y Eva y hermano de Caín. Génesis lo presenta como pastor de ovejas, cuya ofrenda de los primogénitos de su rebaño fue mirada con agrado por Dios; posteriormente fue asesinado por su hermano Caín. El Nuevo Testamento lo recuerda como “justo” y como ejemplo de fe.', 'Publicado básico'),
('glo-abiam-abias-rey-juda', 'Abiam / Abías (rey de Judá; hijo de Roboam)', 'abiam-abias-rey-juda', 'Abiam/Abías fue hijo y sucesor de Roboam y el segundo rey de Judá después de la división del reino. Reinó tres años en Jerusalén; 1 Reyes evalúa negativamente su fidelidad religiosa, mientras que 2 Crónicas destaca su confrontación con Jeroboam, su discurso en el monte Zemaraim y la victoria de Judá. Su hijo Asa lo sucedió en el trono.', 'Publicado básico'),
('glo-abimelec-hijo-gedeon', 'Abimelec (hijo de Gedeón/Jerobaal)', 'abimelec-hijo-gedeon', 'Abimelec fue hijo de Gedeón/Jerobaal y de una concubina de Siquem. Tras la muerte de Gedeón obtuvo el apoyo de los líderes de Siquem, hizo matar a sus hermanos —con excepción de Jotam— y fue proclamado rey. El relato lo presenta gobernando tres años antes de que se rompiera su alianza con Siquem; después destruyó la ciudad y murió durante el ataque a Tebes, cuando una mujer dejó caer sobre su cabeza una piedra superior de molino y él pidió a su escudero que lo rematara con la espada. Su historia funciona como una crítica severa al poder obtenido mediante violencia y traición.', 'Publicado básico'),
('glo-abisag-sunamita', 'Abisag sunamita', 'abisag-sunamita', 'Abisag fue una joven sunamita escogida en los últimos días del rey David para atenderlo y ayudar a darle calor. El texto la describe como muy hermosa, señala expresamente que David no tuvo relaciones sexuales con ella y la presenta después en el trasfondo de la sucesión: Adonías pidió casarse con Abisag, petición que Salomón interpretó como ligada a una pretensión al reino.', 'Publicado básico'),
('glo-absalon-hijo-david', 'Absalón (hijo de David)', 'absalon-hijo-david', 'Absalón fue hijo del rey David y de Maaca, hija de Talmai, rey de Gesur. La narrativa de 2 Samuel lo presenta como un príncipe israelita de notable apariencia, hermano de Tamar, vengador de la agresión de Amnón y, más tarde, líder de una rebelión contra David que terminó con su muerte. 2 Samuel destaca de manera excepcional su belleza física y la abundancia de su cabello.', 'Publicado básico'),
('glo-acab-rey-israel', 'Acab (rey de Israel)', 'acab-rey-israel', 'Acab fue hijo y sucesor de Omri, esposo de Jezabel y rey de Israel con capital en Samaria durante veintidós años. 1 Reyes lo presenta en conflicto repetido con el profeta Elías, involucrado en guerras con Aram y responsable, junto con Jezabel, del caso de la viña de Nabot; murió después de ser herido en batalla en Ramot de Galaad.', 'Publicado básico'),
('glo-acaz-rey-juda', 'Acaz (rey de Judá)', 'acaz-rey-juda', 'Acaz fue hijo de Jotam, rey de Judá, y reinó en Jerusalén durante dieciséis años. Su gobierno estuvo marcado por la guerra siro-efraimita, su recurso a Tiglat-pileser III de Asiria y profundas alteraciones religiosas en Judá.', 'Publicado básico'),
('glo-adan', 'Adán', 'adan', 'Adán es presentado en Génesis como el primer hombre: Dios lo forma del polvo de la tierra, le da aliento de vida, lo coloca en Edén y le da a Eva como esposa. Después de su desobediencia, ambos son expulsados del jardín; Adán aparece luego como padre de Caín, Abel, Set y otros hijos e hijas. En el Nuevo Testamento, Pablo lo identifica como el primer hombre y lo contrasta con Cristo en su exposición sobre pecado, muerte y vida.', 'Publicado básico'),
('glo-adonias-hijo-david', 'Adonías (hijo de David y Haguit)', 'adonias-hijo-david', 'Hijo de David y Haguit y uno de los hijos nacidos en Hebrón. Cuando David envejeció, Adonías intentó adelantarse en la sucesión proclamando su aspiración al trono, organizó una exhibición propia de un pretendiente real y obtuvo el apoyo de Joab y del sacerdote Abiatar; David, sin embargo, hizo reconocer a Salomón como rey. Después, Adonías pidió a Abisag sunamita por esposa, solicitud que Salomón interpretó como una nueva pretensión dinástica y que terminó con la muerte de Adonías.', 'Publicado básico'),
('glo-agar', 'Agar', 'agar', 'Agar es presentada en Génesis como la sierva egipcia de Sarai. Ante la falta de hijos de Sarai, fue dada a Abram para que concibiera por medio de ella; Agar dio a luz a Ismael. Más adelante, ella e Ismael fueron enviados fuera de la casa de Abraham, y el relato describe la provisión de Dios para ambos en el desierto. Génesis la identifica explícitamente como egipcia y como mujer en condición servil dentro de la casa de Sarai.', 'Publicado básico'),
('glo-ahias-silonita-profeta', 'Ahías silonita (profeta)', 'ahias-silonita-profeta', 'Profeta de Silo activo en la transición entre el reinado de Salomón y el surgimiento del reino del norte. Anunció a Jeroboam que recibiría diez tribus mediante el signo de romper una vestidura nueva en doce partes; más tarde, ya anciano, comunicó juicio contra la casa de Jeroboam. 1 Reyes 12:15 presenta la división del reino como cumplimiento de la palabra dada por medio de Ahías.', 'Publicado básico'),
('glo-ahitofel-gilonita', 'Ahitofel gilonita', 'ahitofel-gilonita', 'Consejero de David procedente de Gilo que, durante la rebelión de Absalón, abandonó al rey y pasó a asesorar al hijo rebelde. El relato destaca la extraordinaria autoridad que tenía su consejo; cuando Absalón prefirió la estrategia de Husai y su propio plan fue desechado, Ahitofel regresó a su ciudad, puso en orden su casa y se quitó la vida.', 'Publicado básico'),
('glo-aholiab-artesano-del-tabernaculo', 'Aholiab (artesano del tabernáculo)', 'aholiab-artesano-del-tabernaculo', 'Hijo de Ahisamac, de la tribu de Dan, Aholiab fue designado junto con Bezaleel para la obra artesanal del tabernáculo. El texto lo presenta con capacidad para enseñar y lo vincula con trabajos de artífice, diseñador y recamador en azul, púrpura, carmesí y lino fino.', 'Publicado básico'),
('glo-aman-hijo-hamedata', 'Amán (hijo de Hamedata; agagueo)', 'aman-hijo-hamedata', 'Alto funcionario de Asuero en el libro de Ester. Después de ser elevado sobre los demás príncipes, reaccionó contra Mardoqueo por negarse a inclinarse ante él y promovió un decreto para destruir a los judíos del imperio; Ester finalmente expuso su plan ante el rey, y Amán murió en la misma estructura que había preparado para Mardoqueo.', 'Publicado básico'),
('glo-amasias-rey-juda', 'Amasías (rey de Judá)', 'amasias-rey-juda', 'Hijo y sucesor del rey Joás de Judá. Amasías subió al trono a los 25 años y reinó 29 años en Jerusalén; consolidó su autoridad castigando a los asesinos de su padre sin ejecutar a sus hijos, derrotó a Edom y posteriormente desafió a Joás de Israel, fue vencido en Bet-semes y capturado, y años después murió en una conspiración tras huir a Laquis.', 'Publicado básico'),
('glo-amasias-sacerdote-betel-amos7', 'Amasías (sacerdote de Bet-el; Amós 7)', 'amasias-sacerdote-betel-amos7', 'Amasías fue el sacerdote de Bet-el que denunció ante Jeroboam II la predicación de Amós y luego ordenó al profeta que abandonara Bet-el. El propio relato vincula su función sacerdotal con un santuario estrechamente asociado a la monarquía del reino de Israel.', 'Publicado básico'),
('glo-amnon-hijo-david', 'Amnón (hijo de David)', 'amnon-hijo-david', 'Amnón fue el primogénito de David, nacido en Hebrón de Ahinoam jezreelita. En 2 Samuel 13 engañó a Tamar, su media hermana, para dejarla sola con él y la violó; dos años después, Absalón ordenó matarlo durante una celebración en Baal-hazor como venganza por lo sucedido.', 'Publicado básico'),
('glo-amos-profeta-tecoa', 'Amós (profeta de Tecoa)', 'amos-profeta-tecoa', 'Profeta originario de Tecoa, en Judá, activo durante los reinados de Uzías de Judá y Jeroboam II de Israel. El propio libro lo presenta ligado al cuidado de ganado y de sicómoros antes de ser llamado a profetizar a Israel; su confrontación con Amasías en Bet-el deja claro que su autoridad profética no dependía de una profesión o gremio profético, sino del llamado recibido.', 'Publicado básico'),
('glo-ana-madre-samuel', 'Ana (madre de Samuel)', 'ana-madre-samuel', 'Esposa de Elcana y madre del profeta Samuel. En Silo, Ana oró con profunda aflicción y formuló un voto respecto del hijo que pedía; después del nacimiento y destete de Samuel, lo llevó al santuario para dedicarlo al servicio de Dios. Su relato continúa con un cántico de alabanza y con sus visitas anuales, en las que llevaba a Samuel una pequeña túnica hecha por ella.', 'Publicado básico'),
('glo-ana-profetisa-hija-fanuel', 'Ana (profetisa; hija de Fanuel)', 'ana-profetisa-hija-fanuel', 'Profetisa anciana, hija de Fanuel y de la tribu de Aser, que aparece en el Templo de Jerusalén durante la presentación de Jesús. Lucas la describe dedicada al servicio de Dios con ayunos y oraciones; al encontrarse con el niño, dio gracias a Dios y habló de él a quienes esperaban la redención de Jerusalén.', 'Publicado básico'),
('glo-andres-apostol', 'Andrés (apóstol; hermano de Pedro)', 'andres-apostol', 'Discípulo de Jesús, hermano de Simón Pedro y uno de los Doce. Los Evangelios lo presentan como pescador del mar de Galilea; en Juan aparece primero siguiendo a Jesús y llevando a su hermano Simón ante él, después señalando al muchacho que tenía cinco panes de cebada y dos peces, y más tarde acompañando a Felipe cuando unos griegos quisieron acercarse a Jesús.', 'Publicado básico'),
('glo-aod-hijo-gera', 'Aod (hijo de Gera; juez y libertador)', 'aod-hijo-gera', 'Aod fue un benjaminita, hijo de Gera, levantado por Dios como libertador frente al dominio de Eglón, rey de Moab. El relato de Jueces 3 lo presenta como zurdo: llevó el tributo a Eglón, ocultó bajo su ropa una espada corta de dos filos sobre el muslo derecho, mató al rey y después reunió a Israel para derrotar a los moabitas.', 'Publicado básico'),
('glo-apolos-hechos18', 'Apolos de Alejandría (Hechos 18–19)', 'apolos-hechos18', 'Judío natural de Alejandría que llegó a Éfeso siendo un hombre elocuente y competente en las Escrituras. Enseñaba con fervor acerca de Jesús, aunque conocía solamente el bautismo de Juan; Priscila y Aquila le explicaron con mayor precisión el camino de Dios. Después pasó a Acaya, donde ayudó a los creyentes y defendió públicamente, a partir de las Escrituras, que Jesús es el Cristo. Más tarde Pablo lo presenta como colaborador en la obra de Dios, especialmente en relación con Corinto.', 'Publicado básico'),
('glo-aquila-hechos18', 'Aquila (colaborador de Pablo)', 'aquila-hechos18', 'Aquila fue un judío originario del Ponto, esposo de Priscila/Prisca y colaborador de Pablo. Hechos lo sitúa en Corinto después de haber llegado desde Italia por la orden de Claudio contra los judíos de Roma; compartió oficio y trabajo con Pablo, viajó con él hacia Éfeso y, junto con Priscila, instruyó con mayor precisión a Apolos. Pablo posteriormente los llama colaboradores suyos y menciona una iglesia reunida en su casa.', 'Publicado básico'),
('glo-arauna-ornan-jebuseo', 'Arauna / Ornán jebuseo', 'arauna-ornan-jebuseo', 'Jebuseo propietario de la era que David compró en Jerusalén para levantar un altar durante el episodio de la plaga. Samuel lo llama Arauna y Crónicas Ornán; Crónicas vincula posteriormente esa misma era con el lugar preparado para el templo de Salomón.', 'Publicado básico'),
('glo-artajerjes-rey-persia-esdras', 'Artajerjes (rey de Persia en Esdras–Nehemías)', 'artajerjes-rey-persia-esdras', 'Rey del Imperio persa mencionado en Esdras y Nehemías. En Esdras aparece en correspondencia oficial relacionada con Jerusalén y como el monarca que autoriza la misión de Esdras; en Nehemías es el rey a quien sirve Nehemías como copero y de quien recibe autorización para ir a Jerusalén y gobernar Judá.', 'Publicado básico'),
('glo-asa-rey-juda', 'Asa (rey de Judá)', 'asa-rey-juda', 'Asa fue hijo y sucesor de Abías y rey de Judá durante cuarenta y un años en Jerusalén. El relato bíblico lo evalúa en términos generalmente positivos por sus reformas religiosas y su fidelidad, aunque también registra una etapa final problemática: buscó apoyo del rey de Siria contra Baasa, encarceló al vidente Hanani y terminó su reinado con una grave enfermedad en los pies.', 'Publicado básico'),
('glo-asuero-rey-ester', 'Asuero (rey del imperio persa; Ester)', 'asuero-rey-ester', 'Asuero gobierna un vasto imperio desde Susa y es la autoridad real central del relato de Ester. Organiza los banquetes de apertura, depone a Vasti, recibe después a Ester como reina, eleva a Amán y le entrega su anillo de sello, y más tarde autoriza a Ester y Mardoqueo a actuar para proteger a los judíos.', 'Publicado básico'),
('glo-atalia-reina-juda', 'Atalía (reina de Judá)', 'atalia-reina-juda', 'Atalía fue esposa de Joram, madre del rey Ocozías y gobernante de Judá después de la muerte de su hijo. Según 2 Reyes 11 y 2 Crónicas 22–23, intentó eliminar a la descendencia real, pero Joás fue ocultado; seis años después fue proclamado rey mediante la acción encabezada por el sacerdote Joiada, y Atalía perdió el poder y murió fuera del recinto del templo.', 'Publicado básico'),
('glo-azarias-hijo-oded-profeta', 'Azarías (hijo de Obed; profeta en tiempos de Asa)', 'azarias-hijo-oded-profeta', 'Profeta de Judá presentado en 2 Crónicas 15. El Espíritu de Dios vino sobre Azarías; salió al encuentro del rey Asa y exhortó a Asa, Judá y Benjamín a buscar a YHWH y mantenerse firmes. Su mensaje precede e impulsa la continuación de la reforma religiosa de Asa y la renovación del altar.', 'Publicado básico'),
('glo-azarias-sumo-sacerdote-uzias', 'Azarías (sumo sacerdote que confrontó a Uzías)', 'azarias-sumo-sacerdote-uzias', 'Sumo sacerdote de Judá que, acompañado por ochenta sacerdotes, se enfrentó al rey Uzías cuando este entró al santuario para quemar incienso. Azarías declaró que esa función correspondía a los sacerdotes descendientes de Aarón; después, al aparecer la afección en la frente de Uzías, Azarías y los demás sacerdotes lo hicieron salir del templo.', 'Publicado básico'),
('glo-azarias-uzias-rey-juda', 'Azarías / Uzías (rey de Judá)', 'azarias-uzias-rey-juda', 'Hijo de Amasías y rey de Judá. Comenzó a reinar a los dieciséis años y el texto bíblico atribuye a su largo reinado fortificación, expansión militar, organización del ejército y una fuerte actividad agrícola. Reyes lo llama principalmente Azarías, mientras Crónicas y los libros proféticos usan ampliamente Uzías para la misma identidad real.', 'Publicado básico'),
('glo-baasa-rey-israel', 'Baasa (rey de Israel)', 'baasa-rey-israel', 'Baasa, hijo de Ahías y de la casa de Isacar, tomó el trono del reino del norte al matar al rey Nadab durante el sitio de Gibetón. Después eliminó la casa de Jeroboam, gobernó Israel desde Tirsa durante veinticuatro años y mantuvo conflicto con Asa de Judá. El profeta Jehú hijo de Hanani anunció juicio contra su casa; Baasa murió y fue sepultado en Tirsa, y su hijo Ela lo sucedió.', 'Publicado básico'),
('glo-barrabas-preso-mateo', 'Barrabás (preso liberado en la pasión)', 'barrabas-preso-mateo', 'Preso conocido que fue liberado por Pilato en lugar de Jesús durante la pasión. Mateo lo presenta como un «preso famoso»; Marcos y Lucas lo relacionan con una revuelta en la que hubo homicidio, y Juan lo llama lēstēs, término que puede referirse a ladrón, bandido o insurgente violento según el contexto.', 'Publicado básico'),
('glo-bartimeo-hijo-timeo', 'Bartimeo (hijo de Timeo)', 'bartimeo-hijo-timeo', 'Mendigo ciego nombrado por Marcos que estaba sentado junto al camino cuando Jesús salía de Jericó. Al oír que pasaba Jesús, clamó a él como “Hijo de David”; cuando fue llamado, dejó su manto, se acercó a Jesús, recibió la vista y luego lo siguió por el camino. Marcos es el único Evangelio canónico que lo identifica por nombre.', 'Publicado básico'),
('glo-bartolome-apostol', 'Bartolomé (apóstol)', 'bartolome-apostol', 'Uno de los Doce apóstoles escogidos por Jesús. El Nuevo Testamento lo nombra en las listas apostólicas de Mateo, Marcos y Lucas, y nuevamente entre los discípulos reunidos después de la ascensión en Hechos. Los textos canónicos no narran acciones individuales de Bartolomé ni describen su apariencia.', 'Publicado básico'),
('glo-belsasar-rey-caldeos-daniel', 'Belsasar (rey de los caldeos en Daniel)', 'belsasar-rey-caldeos-daniel', 'Gobernante presentado en Daniel como “rey de los caldeos”, protagonista del banquete de Daniel 5. Durante la fiesta mandó usar los vasos tomados del templo de Jerusalén; después apareció la escritura en la pared, Daniel interpretó el juicio anunciado y Belsasar murió aquella misma noche. Daniel 7:1 y 8:1 también datan visiones en su primer y tercer año de gobierno.', 'Publicado básico'),
('glo-benadad-rey-siria-1reyes20', 'Ben-adad (rey de Siria; 1 Reyes 20)', 'benadad-rey-siria-1reyes20', 'Rey de Siria que, acompañado por una coalición de treinta y dos reyes, sitió Samaria durante el reinado de Acab. Tras exigir riquezas y miembros de la casa real, fue derrotado por Israel; al año siguiente volvió a combatir en Afec, sufrió una segunda derrota y finalmente obtuvo de Acab un pacto que incluía la devolución de ciudades y concesiones comerciales en Damasco.', 'Publicado básico'),
('glo-benadad-rey-siria-2reyes6-8', 'Ben-adad (rey de Siria; 2 Reyes 6–8)', 'benadad-rey-siria-2reyes6-8', 'Rey de Siria que reunió su ejército y sitió Samaria, provocando una grave hambruna. Más adelante, estando enfermo en Damasco, envió a Hazael con presentes para consultar por medio de Eliseo si sanaría; poco después murió y Hazael reinó en su lugar.', 'Publicado básico'),
('glo-benaia-hijo-joiada', 'Benaía (hijo de Joiada)', 'benaia-hijo-joiada', 'Benaía hijo de Joiada, de Cabseel, fue uno de los guerreros más destacados de David. El relato le atribuye grandes proezas, incluida la muerte de un león en un foso durante una nevada y la derrota de un egipcio armado con lanza; David lo puso al frente de su guardia personal. Durante la sucesión apoyó a Salomón y, bajo su reinado, terminó ocupando el mando del ejército en lugar de Joab.', 'Publicado básico'),
('glo-bernabe-hechos', 'Bernabé / José llamado Bernabé', 'bernabe-hechos', 'José, levita originario de Chipre, recibió de los apóstoles el sobrenombre Bernabé. Hechos lo presenta entregando el producto de una propiedad a la comunidad, respaldando a Saulo ante los discípulos de Jerusalén, sirviendo en Antioquía y participando con Pablo en la misión; después de su desacuerdo sobre Juan Marcos, Bernabé partió con Marcos hacia Chipre.', 'Publicado básico'),
('glo-betsabe-hija-eliam', 'Betsabé / Bet-súa (madre de Salomón)', 'betsabe-hija-eliam', 'Betsabé fue hija de Eliam, esposa de Urías heteo y, después de la muerte de Urías, esposa de David. Fue madre de Salomón y tuvo un papel activo en la sucesión real: habló ante David en favor del cumplimiento de su promesa respecto de Salomón y, ya durante el reinado de su hijo, aparece recibiendo un lugar de especial honor como madre del rey.', 'Publicado básico'),
('glo-bezaleel-artesano-del-tabernaculo', 'Bezaleel (artesano del tabernáculo)', 'bezaleel-artesano-del-tabernaculo', 'Bezaleel, hijo de Uri y nieto de Hur, de la tribu de Judá, fue llamado por Dios para dirigir y ejecutar trabajos del tabernáculo. Éxodo lo presenta dotado de sabiduría, inteligencia, conocimiento y habilidad para diseñar y trabajar metales, piedras, madera y textiles, junto con Aholiab y otros artesanos capacitados.', 'Publicado básico'),
('glo-bildad-suhita-job', 'Bildad suhita (amigo de Job)', 'bildad-suhita-job', 'Bildad es uno de los tres amigos de Job que acuden para condolerse de él y consolarlo. Interviene con tres discursos —Job 8, 18 y 25— en los que defiende con fuerza la justicia de Dios y relaciona el destino del malvado con el juicio divino; al final del libro queda incluido entre los amigos reprendidos por Dios y cumple la instrucción dada junto con Elifaz y Zofar.', 'Publicado básico'),
('glo-booz-belen', 'Booz (de Belén)', 'booz-belen', 'Booz fue un hombre destacado y propietario de tierras en Belén, pariente de la familia de Elimelec. En el relato de Rut protege a Rut durante la siega, actúa como pariente-redentor después de que el pariente más cercano renuncia a ese derecho, se casa con Rut y llega a ser padre de Obed, abuelo de Isaí y bisabuelo de David. Rut 4 presenta la transacción ante los ancianos en la puerta de la ciudad y vincula explícitamente a Booz con la línea de David.', 'Publicado básico'),
('glo-caifas-sumo-sacerdote', 'Caifás (sumo sacerdote)', 'caifas-sumo-sacerdote', 'Caifás fue el sumo sacerdote judío durante una parte central del ministerio de Jesús y durante su pasión. Los Evangelios lo sitúan entre los principales dirigentes que deliberaron sobre Jesús; Juan lo presenta proponiendo que convenía que un hombre muriera por el pueblo, y Mateo señala que Jesús fue llevado ante él después de su arresto. Hechos todavía lo menciona entre el círculo sumosacerdotal cuando Pedro y Juan fueron interrogados.', 'Publicado básico'),
('glo-cain', 'Caín', 'cain', 'Caín fue hijo de Adán y Eva y hermano de Abel. Génesis lo presenta como labrador de la tierra; llevó a Dios una ofrenda del fruto del suelo y, después, mató a Abel en el campo. Como consecuencia recibió juicio, quedó asociado con una vida de fugitivo y errante, recibió de Dios una señal protectora cuya forma no se describe y habitó en la tierra de Nod, al oriente de Edén.', 'Publicado básico'),
('glo-cam-hijo-de-noe', 'Cam (hijo de Noé)', 'cam-hijo-de-noe', 'Cam fue uno de los tres hijos de Noé que entraron en el arca y sobrevivieron al diluvio con sus familias. Génesis lo presenta además como padre de Cus, Mizraim, Fut y Canaán, y lo incluye entre los antepasados de los pueblos enumerados en la Tabla de las Naciones.', 'Publicado básico'),
('glo-carcelero-filipos-hechos16', 'Carcelero de Filipos (sin nombre)', 'carcelero-filipos-hechos16', 'Funcionario anónimo encargado de la cárcel de Filipos cuando Pablo y Silas fueron encarcelados. Tras el terremoto nocturno, al comprobar que los presos no habían escapado, escuchó el mensaje de Pablo y Silas, atendió sus heridas y fue bautizado junto con los de su casa. Hechos también lo muestra transmitiendo después la orden de liberación enviada por los magistrados.', 'Publicado básico'),
('glo-ciego-nacimiento-juan9', 'Hombre ciego de nacimiento (Juan 9)', 'ciego-nacimiento-juan9', 'Varón anónimo presentado en Juan 9 como ciego desde su nacimiento. Jesús hizo barro, lo puso sobre sus ojos y le indicó lavarse en el estanque de Siloé; el hombre volvió viendo. Después fue interrogado por vecinos y autoridades religiosas, defendió públicamente lo que Jesús había hecho y, tras ser expulsado, volvió a encontrarse con Jesús y expresó fe en él.', 'Publicado básico'),
('glo-ciro-rey-persia', 'Ciro (rey de Persia)', 'ciro-rey-persia', 'Ciro II, conocido históricamente como Ciro el Grande, fue el fundador del Imperio aqueménida y el rey persa que conquistó Babilonia en 539 a. C. En la Biblia ocupa un lugar excepcional: 2 Crónicas y Esdras lo presentan autorizando la reconstrucción del templo de Jerusalén y el regreso de quienes quisieran participar, mientras Isaías lo llama pastor de YHWH y su “ungido”, instrumento mediante el cual Dios ejecuta su propósito histórico. Históricamente, Ciro gobernó un imperio expansivo desde mediados del siglo VI a. C. y murió hacia 530 a. C.', 'Publicado básico'),
('glo-cleofas-emaus', 'Cleofas (discípulo camino a Emaús)', 'cleofas-emaus', 'Cleofas fue uno de los dos discípulos que viajaban de Jerusalén a Emaús el día de la resurrección de Jesús. Lucas lo nombra explícitamente cuando responde al desconocido que se une a ellos en el camino; más tarde, ambos discípulos reconocen a Jesús al partir el pan y regresan a Jerusalén para contar lo sucedido.', 'Publicado básico'),
('glo-cornelio-centurion-hechos10', 'Cornelio (centurión en Cesarea)', 'cornelio-centurion-hechos10', 'Cornelio fue un centurión residente en Cesarea, perteneciente a la unidad que Hechos llama la «compañía Italiana». Hechos 10 lo presenta como gentil piadoso y temeroso de Dios, dedicado a la oración y a dar limosnas; tras recibir una visión, mandó llamar a Pedro. Durante la visita de Pedro, el Espíritu Santo descendió sobre Cornelio y quienes lo escuchaban, un episodio decisivo en la incorporación de gentiles a la comunidad cristiana.', 'Publicado básico'),
('glo-dalila', 'Dalila', 'dalila', 'Dalila es la mujer del valle de Sorec a quien Sansón amó. Los gobernantes filisteos le ofrecieron una gran recompensa para descubrir el origen de la fuerza de Sansón; después de insistir repetidamente, Sansón le reveló lo relacionado con su consagración y su cabello, y Dalila coordinó su entrega a los filisteos. El texto bíblico no la llama prostituta ni afirma que fuera filistea.', 'Publicado básico'),
('glo-daniel-profeta', 'Daniel (profeta)', 'daniel-profeta', 'Daniel es el personaje central del libro de Daniel. El relato lo presenta como un joven judío llevado a Babilonia, formado para el servicio de la corte y dotado por Dios de sabiduría y capacidad para comprender sueños y visiones. Más adelante aparece como alto funcionario bajo dominio medo-persa, fiel a la oración aun bajo amenaza de muerte, y como receptor de las visiones proféticas de Daniel 7–12. Mateo 24:15 lo denomina explícitamente “el profeta Daniel”.', 'Publicado básico'),
('glo-david-rey-israel', 'David (rey de Israel)', 'david-rey-israel', 'David, hijo de Isaí de Belén, fue ungido por Samuel mientras Saúl aún reinaba. Tras servir en la corte y el ejército de Saúl, llegó a reinar primero sobre Judá en Hebrón y después sobre todo Israel desde Jerusalén; 2 Samuel lo presenta como fundador de una dinastía real a la que Dios promete continuidad. El relato bíblico también conserva sin idealización sus graves pecados en el episodio de Betsabé y Urías y la reprensión posterior de Natán.', 'Publicado básico'),
('glo-debora-profetisa-jueza', 'Débora (profetisa y jueza)', 'debora-profetisa-jueza', 'Débora fue una profetisa que gobernaba/juzgaba a Israel durante el período narrado en Jueces. La RVR1960 la presenta como “mujer de Lapidot”, sentada bajo la palmera de Débora entre Ramá y Bet-el, donde los israelitas acudían a ella a juicio. Ella transmitió a Barac la orden divina de enfrentar a Sísara, lo acompañó en la campaña y después cantó con él la victoria narrada en Jueces 5.', 'Publicado básico'),
('glo-eli-sacerdote-juez', 'Elí (sacerdote y juez)', 'eli-sacerdote-juez', 'Elí fue sacerdote en Silo y juez de Israel durante la etapa final del período de los jueces. Recibió al joven Samuel en el servicio del santuario, reconoció que Jehová lo estaba llamando y le indicó cómo responder. Su historia también queda marcada por la corrupción de sus hijos Ofni y Finees y por el juicio anunciado contra su casa.', 'Publicado básico'),
('glo-elias-tisbita', 'Elías tisbita', 'elias-tisbita', 'Elías fue un profeta de Israel que aparece durante el reinado de Acab. Confrontó el culto a Baal, anunció la sequía, actuó en el monte Carmelo y posteriormente participó en la transición profética que culminó con Eliseo. El relato bíblico lo presenta como «el tisbita» y lo asocia con Galaad, aunque la localización exacta de Tisbe no puede establecerse con seguridad.', 'Publicado básico'),
('glo-elifaz-temanita-job', 'Elifaz temanita (amigo de Job)', 'elifaz-temanita-job', 'Elifaz temanita fue uno de los tres amigos de Job que acudieron a acompañarlo en su sufrimiento. Tras guardar silencio con él durante siete días, fue el primero en hablar y desarrolló una explicación del sufrimiento basada en la retribución moral; al final del libro, Jehová reprende a Elifaz y a sus compañeros por no haber hablado correctamente acerca de Él como Job. Sus discursos principales aparecen en Job 4–5, 15 y 22.', 'Publicado básico'),
('glo-elisabet-madre-juan-bautista', 'Elisabet (madre de Juan el Bautista)', 'elisabet-madre-juan-bautista', 'Elisabet fue esposa del sacerdote Zacarías y madre de Juan el Bautista. Lucas la presenta como descendiente de Aarón, justa delante de Dios y de edad avanzada; después de años sin hijos concibió a Juan, recibió a María durante su embarazo y reconoció con gozo la significación de la visita.', 'Publicado básico'),
('glo-eliseo-hijo-safat', 'Eliseo (hijo de Safat)', 'eliseo-hijo-safat', 'Eliseo fue profeta de Israel y sucesor de Elías. Hijo de Safat, fue llamado mientras araba, dejó su actividad agrícola para servir a Elías y, tras la partida de este, fue reconocido por los hijos de los profetas como su sucesor. Su ministerio, narrado principalmente en 2 Reyes, incluye oráculos a reyes, auxilio a comunidades proféticas y diversos milagros vinculados a la provisión, sanidad y restauración.', 'Publicado básico'),
('glo-eliu-hijo-baraquel-job', 'Eliú hijo de Baraquel (buzita; Job)', 'eliu-hijo-baraquel-job', 'Eliú es el hijo de Baraquel, identificado como buzita y de la familia de Ram. En Job 32–37 toma la palabra después de Job, Elifaz, Bildad y Zofar; había esperado porque ellos eran mayores que él, pero interviene al considerar insuficientes sus respuestas y al querer defender la justicia de Dios.', 'Publicado básico'),
('glo-enoc-descendiente-de-set-hijo-de-jared', 'Enoc (descendiente de Set; hijo de Jared)', 'enoc-descendiente-de-set-hijo-de-jared', 'Enoc fue hijo de Jared, padre de Matusalén y miembro de la línea de Set. Génesis destaca que caminó con Dios y que, tras 365 años de vida, desapareció porque Dios se lo llevó; Hebreos interpreta este hecho como un traslado por fe para no ver muerte. Judas lo identifica además como “séptimo desde Adán”.', 'Publicado básico'),
('glo-epafras-colaborador-procedente-de-colosas', 'Epafras (colaborador procedente de Colosas)', 'epafras-colaborador-procedente-de-colosas', 'Epafras fue colaborador de Pablo y ministro de Cristo vinculado a la comunidad de Colosas. Los colosenses habían recibido de él enseñanza sobre el evangelio; Pablo lo presenta como consiervo amado y fiel ministro, y más adelante como uno de ellos, intensamente dedicado a orar por Colosas y preocupado también por los creyentes de Laodicea e Hierápolis. Filemón 23 lo identifica como compañero de prisión de Pablo en Cristo Jesús.', 'Publicado básico'),
('glo-epafrodito-colaborador-mensajero-filipenses', 'Epafrodito (colaborador y mensajero de Filipenses)', 'epafrodito-colaborador-mensajero-filipenses', 'Epafrodito fue un creyente vinculado a la iglesia de Filipos y colaborador de Pablo. Pablo lo llama hermano, colaborador y compañero de milicia, además de mensajero de los filipenses y servidor de sus necesidades; también indica que Epafrodito llevó a Pablo la ayuda enviada por esa comunidad. Durante esa misión enfermó gravemente y estuvo cerca de morir, pero se recuperó y Pablo decidió enviarlo de regreso, pidiendo que fuera recibido con gozo y honor.', 'Publicado básico'),
('glo-esau', 'Esaú', 'esau', 'Esaú fue el hijo mayor de Isaac y Rebeca y hermano gemelo de Jacob. Génesis lo presenta como cazador hábil y hombre del campo; vendió su primogenitura a Jacob, perdió la bendición paterna mediante el engaño de Jacob y Rebeca y más tarde se reconcilió con su hermano. Génesis 36 lo identifica también con Edom y como antepasado de los edomitas.', 'Publicado básico'),
('glo-esdras-sacerdote-escriba', 'Esdras (sacerdote y escriba)', 'esdras-sacerdote-escriba', 'Esdras fue un sacerdote descendiente de Aarón y un escriba experto en la Ley de Moisés. Subió de Babilonia a Jerusalén durante el reinado de Artajerjes; el texto destaca que dispuso su corazón para estudiar, cumplir y enseñar la Ley, y posteriormente aparece leyendo públicamente el libro de la Ley ante el pueblo.', 'Publicado básico'),
('glo-esteban-testigo-martir-hechos', 'Esteban (testigo y mártir en Hechos)', 'esteban-testigo-martir-hechos', 'Esteban fue un discípulo de la iglesia de Jerusalén, uno de los Siete escogidos para atender una necesidad comunitaria. Hechos lo presenta como un varón de buen testimonio, lleno de fe, del Espíritu Santo, de gracia y de poder; realizó prodigios y señales, defendió públicamente su testimonio ante el concilio y murió apedreado mientras invocaba a Jesús y pedía perdón por sus agresores.', 'Publicado básico'),
('glo-ester-hadasa-reina', 'Ester / Hadasa (reina en Susa)', 'ester-hadasa-reina', 'Ester, cuyo nombre hebreo era Hadasa, fue una joven judía huérfana criada por Mardoqueo en Susa. Fue llevada a la casa real, llegó a ser reina en lugar de Vasti y, más adelante, arriesgó su vida al presentarse ante el rey para interceder por su pueblo frente al decreto impulsado por Amán. Ester 2 establece su identidad, su incorporación a la corte y su coronación; Ester 4–8 desarrolla su intervención decisiva.', 'Publicado básico'),
('glo-eunuco-etiope-hechos8', 'Funcionario eunuco de Candace (Hechos 8; sin nombre)', 'eunuco-etiope-hechos8', 'Hombre etíope —en el sentido antiguo del territorio al sur de Egipto— descrito en Hechos como eunuco y alto funcionario de Candace, encargado de todo su tesoro. Había viajado a Jerusalén para adorar y, mientras regresaba leyendo al profeta Isaías, Felipe le explicó el pasaje acerca de Jesús; después pidió ser bautizado y siguió su camino con gozo.', 'Publicado básico'),
('glo-eutico-hechos20', 'Eutico (Hechos 20)', 'eutico-hechos20', 'Eutico fue un joven de Troas presente en una reunión de los discípulos durante la visita de Pablo. Mientras Pablo hablaba hasta avanzada la noche, Eutico se quedó profundamente dormido sentado en una ventana, cayó desde el tercer piso y fue recogido muerto; después de que Pablo descendiera y lo abrazara, el joven fue llevado vivo, causando gran consuelo a la comunidad. Hechos no aporta más datos biográficos sobre él.', 'Publicado básico'),
('glo-eva', 'Eva', 'eva', 'Eva es la primera mujer presentada en Génesis. Dios la forma a partir del hombre como su correspondiente compañera; después de la transgresión, Adán la llama Eva porque sería “madre de todos los vivientes”. Génesis también la presenta como madre de Caín, Abel y Set.', 'Publicado básico'),
('glo-ezequias-rey-juda', 'Ezequías (rey de Judá)', 'ezequias-rey-juda', 'Ezequías, hijo de Acaz, fue rey de Judá y gobernó veintinueve años en Jerusalén. El relato bíblico lo destaca por su confianza en Jehová, sus reformas religiosas, la restauración del culto del templo, su respuesta a la invasión asiria de Senaquerib y su enfermedad seguida de recuperación. Su reinado también quedó asociado a importantes obras defensivas e hidráulicas en Jerusalén.', 'Publicado básico'),
('glo-ezequiel-profeta', 'Ezequiel (profeta)', 'ezequiel-profeta', 'Ezequiel fue sacerdote y profeta, hijo de Buzi, que recibió su llamado profético mientras vivía entre los desterrados de Judá junto al río Quebar, en tierra de los caldeos. Su ministerio acompañó a la comunidad exiliada antes y después de la caída de Jerusalén, mediante visiones, mensajes proféticos y actos simbólicos que anunciaban juicio, responsabilidad y restauración.', 'Publicado básico'),
('glo-faraon-del-exodo-exodo-5-14', 'Faraón del éxodo (Éxodo 5-14)', 'faraon-del-exodo-exodo-5-14', 'Rey de Egipto que, en Éxodo 5–14, se niega repetidamente a dejar salir a Israel, aumenta la carga de trabajo, enfrenta las señales y plagas anunciadas por Moisés y Aarón, finalmente permite la salida y después moviliza sus carros y ejército para perseguir al pueblo. El texto bíblico no proporciona su nombre personal, por lo que Bibli no lo identifica con Ramsés II, Amenhotep II ni con ningún otro faraón concreto.', 'Publicado básico'),
('glo-faraon-necao', 'Faraón Necao (rey de Egipto)', 'faraon-necao', 'Necao II fue faraón de Egipto de la dinastía XXVI o saíta, contemporáneo del rey Josías de Judá. En el relato bíblico marchó hacia el Éufrates/Carquemis, se enfrentó con Josías en Meguido, después depuso a Joacaz, puso a Eliaquim —renombrado Joacim— como rey de Judá y llevó a Joacaz a Egipto; Jeremías también sitúa al ejército de Necao en Carquemis frente a Nabucodonosor.', 'Publicado básico'),
('glo-febe-romanos16', 'Febe de Cencrea', 'febe-romanos16', 'Febe es una creyente de la comunidad cristiana de Cencrea a quien Pablo recomienda a los cristianos de Roma. Romanos 16:1–2 la llama ‘hermana’, la describe con el término griego διάκονος (diákonos) de la iglesia en Cencrea y afirma que fue προστάτις (prostátis) de muchos, incluido Pablo. El alcance técnico exacto de diákonos —servidora/ministra o un oficio eclesial ya definido— es discutido, por lo que Bibli conserva esa cautela.', 'Publicado básico'),
('glo-felipe-apostol', 'Felipe (apóstol)', 'felipe-apostol', 'Felipe fue uno de los doce apóstoles escogidos por Jesús. El Evangelio de Juan lo identifica como natural de Betsaida, la misma ciudad de Andrés y Pedro; también lo presenta llamando a Natanael, dialogando con Jesús antes de la alimentación de la multitud, sirviendo de intermediario cuando unos griegos quisieron ver a Jesús y pidiendo que les mostrara al Padre. Los listados apostólicos y Hechos 1 lo distinguen claramente como miembro de los Doce.', 'Publicado básico'),
('glo-felipe-evangelista-hechos', 'Felipe (uno de los Siete / evangelista)', 'felipe-evangelista-hechos', 'Felipe fue uno de los siete hombres escogidos por la comunidad de Jerusalén para atender una necesidad vinculada con la distribución diaria. Más adelante proclamó a Cristo en Samaria, anunció el evangelio al funcionario etíope y, años después, Hechos lo identifica explícitamente como “Felipe el evangelista, que era uno de los siete” y lo sitúa en Cesarea. Hechos también menciona que tenía cuatro hijas que profetizaban.', 'Publicado básico'),
('glo-gedalias-hijo-ahicam-gobernador', 'Gedalías (hijo de Ahicam; gobernador de Judá)', 'gedalias-hijo-ahicam-gobernador', 'Gedalías, hijo de Ahicam y nieto de Safán, fue puesto por Nabucodonosor sobre la población que permaneció en Judá después de la caída de Jerusalén. Establecido en Mizpa, exhortó a los sobrevivientes a permanecer en la tierra y servir al rey de Babilonia; posteriormente fue asesinado por Ismael hijo de Netanías.', 'Publicado básico'),
('glo-giezi-criado-eliseo', 'Giezi (criado de Eliseo)', 'giezi-criado-eliseo', 'Giezi fue criado y asistente del profeta Eliseo. Participa en el relato de la sunamita, recibe encargos directos de Eliseo y, después de la curación de Naamán, engaña al sirio para obtener plata y vestidos; Eliseo descubre el engaño y Giezi queda afectado por la tsaraat de Naamán. También aparece conversando con el rey acerca de las obras de Eliseo.', 'Publicado básico'),
('glo-habacuc-profeta', 'Habacuc (profeta)', 'habacuc-profeta', 'Habacuc es el profeta que da nombre al libro de Habacuc. El texto lo identifica explícitamente como profeta y presenta su mensaje como un diálogo sobre la violencia, la injusticia, el juicio mediante los caldeos y la confianza perseverante en Dios; fuera de su propio libro, la Biblia canónica no aporta datos biográficos seguros sobre él.', 'Publicado básico'),
('glo-hageo-profeta', 'Hageo (profeta)', 'hageo-profeta', 'Hageo fue un profeta de Juda en el periodo posterior al exilio. En el segundo ano del rey persa Dario I transmitio mensajes dirigidos, entre otros, a Zorobabel y al sumo sacerdote Josue, exhortando al pueblo a reanudar la reconstruccion del templo; Esdras lo presenta junto con Zacarias alentando esa obra. Su actividad profetica registrada se situa en 520 a. C.', 'Publicado básico'),
('glo-hazael-rey-siria', 'Hazael (rey de Siria)', 'hazael-rey-siria', 'Hazael fue un funcionario de Ben-adad que llegó a ser rey de Siria/Aram-Damasco. Eliseo anunció que gobernaría Siria; después de la muerte de Ben-adad, Hazael ocupó el trono y se convirtió en un adversario militar de Israel, extendiendo su dominio sobre territorios al este del Jordán y presionando también a Judá.', 'Publicado básico'),
('glo-herodes-agripa-i-hechos12', 'Herodes Agripa I (Hechos 12)', 'herodes-agripa-i-hechos12', 'Herodes Agripa I fue el rey herodiano que aparece en Hechos 12 persiguiendo a miembros de la iglesia: mandó matar a Jacobo, hermano de Juan, encarceló a Pedro y, más tarde, murió en Cesarea después de aceptar una aclamación que lo trataba como divino. El «rey Herodes» de este capítulo se identifica históricamente con Agripa I.', 'Publicado básico'),
('glo-herodes-agripa-ii-hechos25-26', 'Herodes Agripa II (Hechos 25–26)', 'herodes-agripa-ii-hechos25-26', 'Herodes Agripa II fue un rey cliente de Roma de la dinastía herodiana, hijo de Herodes Agripa I. En Hechos 25–26 visita Cesarea junto con Berenice, escucha la defensa de Pablo ante Porcio Festo y, después de la audiencia, concluye con los demás que Pablo no había hecho nada digno de muerte ni de prisión. El relato también presupone que Agripa conocía bien las costumbres y controversias judías.', 'Publicado básico'),
('glo-herodes-antipas-tetrarca', 'Herodes Antipas (tetrarca)', 'herodes-antipas-tetrarca', 'Herodes Antipas fue el gobernante herodiano que ejerció como tetrarca de Galilea durante el ministerio de Juan el Bautista y de Jesús. Los Evangelios lo vinculan con el encarcelamiento y la ejecución de Juan, y Lucas lo presenta interrogando y escarneciendo a Jesús antes de devolverlo a Pilato. Mateo y Lucas lo identifican expresamente como tetrarca.', 'Publicado básico'),
('glo-herodes-el-grande', 'Herodes el Grande', 'herodes-el-grande', 'Herodes el Grande fue el rey de Judea bajo tutela romana durante el período en que sitúan los Evangelios el nacimiento de Jesús. En Mateo 2 recibe a los magos en Jerusalén, se inquieta ante el anuncio del nacimiento del «rey de los judíos», intenta localizar al niño y después ordena la muerte de los niños de Belén y sus alrededores; Lucas 1:5 también sitúa el nacimiento de Juan el Bautista «en los días de Herodes, rey de Judea».', 'Publicado básico'),
('glo-herodias', 'Herodías', 'herodias', 'Herodías es la mujer vinculada en los Evangelios con Herodes Antipas y con el conflicto que llevó al encarcelamiento y muerte de Juan el Bautista. Mateo y Marcos la presentan como esposa de Felipe, hermano de Herodes, y luego vinculada maritalmente con Herodes; Marcos añade que Herodías quería matar a Juan, mientras Mateo muestra que instruyó a su hija para pedir la cabeza de Juan después del baile en el cumpleaños de Herodes. Lucas también señala que Juan reprendía a Herodes por causa de Herodías.', 'Publicado básico'),
('glo-hilcias-sumo-sacerdote-josias', 'Hilcías (sumo sacerdote en tiempos de Josías)', 'hilcias-sumo-sacerdote-josias', 'Hilcías fue el sumo sacerdote de Judá durante el reinado de Josías. Mientras se reparaba la casa de Jehová, halló el libro de la ley, lo entregó al escriba Safán y después formó parte de la delegación enviada por el rey para consultar a Jehová por medio de la profetisa Hulda; también aparece participando en la reforma del templo y en la celebración de la Pascua.', 'Publicado básico'),
('glo-hiram-artesano-bronce-tiro', 'Hiram (artesano de bronce de Tiro)', 'hiram-artesano-bronce-tiro', 'Hiram fue un maestro artesano procedente de Tiro a quien Salomón incorporó a los trabajos del templo. 1 Reyes lo presenta especialmente como experto en bronce, dotado de sabiduría, inteligencia y conocimiento para ese oficio; realizó, entre otras obras, los grandes elementos y utensilios de bronce asociados al templo, incluidos pilares, capiteles, basas, fuentes, el “Mar” y diversos recipientes.', 'Publicado básico'),
('glo-hiram-rey-tiro-david', 'Hiram (rey de Tiro; aliado de David)', 'hiram-rey-tiro-david', 'Hiram fue rey de Tiro y aliado de David y Salomón. Envió a David madera de cedro, carpinteros y canteros para su casa; después mantuvo relaciones diplomáticas y comerciales con Salomón, suministrando madera del Líbano, trabajadores especializados y marineros para proyectos vinculados al Templo y a la navegación. Debe distinguirse expresamente de Hiram/Huram-abi, el artesano tirio.', 'Publicado básico'),
('glo-hulda-profetisa', 'Hulda (profetisa)', 'hulda-profetisa', 'Hulda fue una profetisa de Judá en tiempos del rey Josías. Después del hallazgo del libro de la ley en el templo, el sacerdote Hilcías y otros enviados del rey acudieron a consultarla; Hulda transmitió un oráculo de juicio sobre Jerusalén y Judá, junto con una palabra específica para Josías debido a su humillación ante Dios.', 'Publicado básico'),
('glo-husai-arquita', 'Husai arquita', 'husai-arquita', 'Husai fue un aliado y confidente de David. Durante la rebelión de Absalón, David lo envió de regreso a Jerusalén para frustrar el consejo de Ahitofel; Husai se presentó ante Absalón, consiguió que prevaleciera su propio consejo y luego transmitió información a David mediante los sacerdotes Sadoc y Abiatar. 1 Crónicas lo recuerda como “amigo” del rey junto al consejero Ahitofel.', 'Publicado básico'),
('glo-is-boset-es-baal-hijo-saul', 'Is-boset / Es-baal (hijo de Saúl)', 'is-boset-es-baal-hijo-saul', 'Hijo de Saúl a quien Abner estableció como rey sobre Israel en Mahanaim después de la muerte de Saúl, mientras David reinaba sobre Judá. El texto indica que tenía cuarenta años al comenzar a reinar y que su reinado duró dos años; tras la ruptura con Abner quedó políticamente debilitado y finalmente fue asesinado por Recab y Baana.', 'Publicado básico'),
('glo-isaac', 'Isaac', 'isaac', 'Hijo de Abraham y Sara, nacido conforme a la promesa divina. Fue esposo de Rebeca y padre de Esaú y Jacob; en Génesis, las promesas del pacto dadas a Abraham son reafirmadas a Isaac.', 'Publicado básico'),
('glo-isaias-profeta', 'Isaías (profeta)', 'isaias-profeta', 'Profeta de Judá e hijo de Amoz cuya actividad se sitúa en Jerusalén durante los reinados de Uzías, Jotam, Acaz y Ezequías. Sus oráculos confrontan el pecado y la injusticia de Judá, anuncian juicio y esperanza, y lo muestran interviniendo también en momentos políticos decisivos, especialmente ante la amenaza asiria.', 'Publicado básico'),
('glo-ismael-hijo-abraham', 'Ismael (hijo de Abraham)', 'ismael-hijo-abraham', 'Primer hijo de Abraham, nacido de Agar la egipcia. Génesis relata que Dios oyó y sostuvo al muchacho, prometió hacer de él una gran nación, y que Ismael creció en el desierto, habitó en Parán y llegó a ser tirador de arco; más adelante se enumeran sus doce hijos y se indica que murió a los 137 años.', 'Publicado básico'),
('glo-jacob-israel-patriarca', 'Jacob (Israel, patriarca)', 'jacob-israel-patriarca', 'Hijo de Isaac y Rebeca, hermano gemelo de Esaú y figura patriarcal central de Génesis. Después de su encuentro nocturno junto al Jaboc recibió el nombre Israel; sus hijos forman la base genealógica de las tribus de Israel, y Jacob descendió finalmente a Egipto, donde murió a los 147 años.', 'Publicado básico'),
('glo-jacobo-hermano-senor-jerusalen', 'Jacobo (hermano del Señor; líder en Jerusalén)', 'jacobo-hermano-senor-jerusalen', 'Jacobo es presentado en el Nuevo Testamento como uno de los hermanos de Jesús y, posteriormente, como una figura principal de la comunidad creyente de Jerusalén. Pablo lo llama “el hermano del Señor” y lo incluye entre las figuras consideradas “columnas”; Hechos lo muestra ocupando un papel de liderazgo en la deliberación de Jerusalén y recibiendo a Pablo junto con los ancianos.', 'Publicado básico'),
('glo-jacobo-hijo-alfeo', 'Jacobo (hijo de Alfeo; apóstol)', 'jacobo-hijo-alfeo', 'Uno de los doce apóstoles escogidos por Jesús. El Nuevo Testamento lo identifica de manera estable como Jacobo, hijo de Alfeo en las listas apostólicas de Mateo, Marcos y Lucas, y vuelve a mencionarlo entre los discípulos reunidos en Jerusalén después de la ascensión. No se conservan en el texto bíblico episodios individuales, oficio, edad o rasgos físicos propios de él.', 'Publicado básico'),
('glo-jacobo-hijo-zebedeo', 'Jacobo (hijo de Zebedeo; apóstol)', 'jacobo-hijo-zebedeo', 'Apóstol de Jesús, hijo de Zebedeo y hermano de Juan. Era pescador en Galilea y fue llamado mientras trabajaba con su padre y su hermano; aparece junto con Pedro y Juan en varios momentos especialmente cercanos al ministerio de Jesús, y Hechos registra que Herodes Agripa I lo hizo morir a espada.', 'Publicado básico'),
('glo-jafet', 'Jafet', 'jafet', 'Hijo de Noé y hermano de Sem y Cam. Sobrevivió al diluvio dentro del arca con su familia y, en la tabla de naciones de Génesis 10, aparece como antepasado de varios pueblos vinculados principalmente con regiones al norte y al oeste de Israel. Génesis 9:27 conserva además una bendición de Noé sobre él.', 'Publicado básico'),
('glo-jahaziel-hijo-zacarias-levita', 'Jahaziel (hijo de Zacarías; levita en tiempos de Josafat)', 'jahaziel-hijo-zacarias-levita', 'Levita descendiente de Asaf que, en medio de la asamblea convocada por el rey Josafat ante una amenaza militar, recibió el Espíritu de Jehová y proclamó al pueblo que no debía temer, porque la batalla pertenecía a Dios. Su intervención ocupa 2 Crónicas 20:14–17 y funciona como respuesta profética a la oración pública de Josafat.', 'Publicado básico'),
('glo-jairo-principal-sinagoga', 'Jairo (principal de la sinagoga)', 'jairo-principal-sinagoga', 'Jairo es un dirigente de sinagoga mencionado por nombre en Marcos y Lucas. Acude personalmente a Jesús, se postra ante él y le ruega que intervenga por su hija gravemente enferma; el relato culmina con la restauración de la niña. Marcos lo presenta como uno de los ἀρχισυνάγωγοι, mientras Lucas lo llama ἄρχων τῆς συναγωγῆς, dos formulaciones que lo sitúan en una función de liderazgo comunitario vinculada a la sinagoga.', 'Publicado básico'),
('glo-jefte-galaadita', 'Jefté galaadita', 'jefte-galaadita', 'Jefté es un guerrero galaadita que, tras ser expulsado por sus medio hermanos y vivir en la tierra de Tob, fue llamado por los ancianos de Galaad para dirigir la guerra contra los amonitas. El pueblo lo hizo cabeza y jefe militar; después de la victoria, juzgó a Israel durante seis años.', 'Publicado básico'),
('glo-jehu-casa-nimsi-rey-israel', 'Jehú (casa de Nimsi; rey de Israel)', 'jehu-casa-nimsi-rey-israel', 'Jehú, hijo de Josafat y nieto de Nimsi, fue comandante militar y luego rey del reino del norte de Israel. Fue ungido por mandato profético para derribar la casa de Acab; encabezó el golpe que terminó con Joram, Jezabel y la dinastía omrida, y eliminó el culto estatal a Baal, aunque 2 Reyes también lo critica por mantener los becerros de Bet-el y Dan.', 'Publicado básico'),
('glo-jeremias-profeta', 'Jeremías (profeta)', 'jeremias-profeta', 'Jeremías, hijo de Hilcías, fue un profeta de Judá procedente de Anatot, en territorio de Benjamín. Su ministerio comenzó en el año decimotercero del rey Josías y continuó durante las últimas décadas del reino de Judá, atravesando los reinados de Joacim y Sedequías, el sitio y la caída de Jerusalén y sus consecuencias. Anunció juicio por la infidelidad del pueblo, llamó al arrepentimiento y proclamó también restauración y un nuevo pacto.', 'Publicado básico'),
('glo-jeroboam-i-hijo-nabat', 'Jeroboam I (hijo de Nabat; rey de Israel)', 'jeroboam-i-hijo-nabat', 'Jeroboam I, hijo de Nabat y efraimita de Zereda, fue un funcionario de Salomón que llegó a ser el primer rey del reino del norte de Israel tras la ruptura con la casa de David. El relato de Reyes vincula su ascenso con la profecía de Ahías y presenta como rasgo decisivo de su reinado el establecimiento de santuarios reales en Bet-el y Dan con becerros de oro, práctica que después se convierte en el paradigma de “hacer pecar a Israel”.', 'Publicado básico'),
('glo-jeroboam-ii-rey-israel', 'Jeroboam II (rey de Israel)', 'jeroboam-ii-rey-israel', 'Jeroboam II, hijo de Joás, fue rey del reino del norte de Israel con sede en Samaria. 2 Reyes le atribuye un reinado de cuarenta y un años, la restauración de los límites de Israel desde la entrada de Hamat hasta el mar del Arabá y victorias militares, pero también lo evalúa negativamente por continuar los pecados asociados con Jeroboam hijo de Nabat.', 'Publicado básico'),
('glo-jesus-presentacion-terrenal', 'Jesús (presentación terrenal)', 'jesus-presentacion-terrenal', 'Jesús de Nazaret es la figura central de los Evangelios y del Nuevo Testamento. Esta entrada representa su apariencia humana ordinaria durante su vida y ministerio terrenal, no la Transfiguración ni su presentación glorificada de Apocalipsis; por eso debe mostrarse como un varón judío del siglo I, sin halo, aura ni luminosidad sobrenatural añadida.', 'Publicado básico'),
('glo-jetro-sacerdote-de-madian-suegro-de-moises', 'Jetro (sacerdote de Madián; suegro de Moisés)', 'jetro-sacerdote-de-madian-suegro-de-moises', 'Jetro es presentado en Éxodo como sacerdote de Madián y suegro de Moisés. Moisés pastoreó sus ovejas antes de regresar a Egipto; después del éxodo, Jetro visitó a Moisés, bendijo a Jehová por la liberación de Israel, presentó holocaustos y sacrificios para Dios y aconsejó a Moisés que delegara responsabilidades judiciales en hombres capaces.', 'Publicado básico'),
('glo-jezabel-reina-israel', 'Jezabel (esposa de Acab)', 'jezabel-reina-israel', 'Jezabel fue hija de Et-baal, rey de los sidonios, y esposa de Acab, rey de Israel. El relato de Reyes la presenta como una figura decisiva en la promoción del culto a Baal, en la persecución de profetas de Jehová y en el complot que terminó con la muerte de Nabot para que Acab tomara su viña.', 'Publicado básico'),
('glo-joab-hijo-sarvia', 'Joab (hijo de Sarvia)', 'joab-hijo-sarvia', 'Joab fue hijo de Sarvia, hermano de Abisai y Asael, y comandante del ejército de David. Fue una figura militar y política decisiva durante el reinado de David: dirigió campañas, intervino en crisis internas y mantuvo gran influencia, pero el relato también registra actos de violencia por los que finalmente fue juzgado; después de apoyar a Adonías, murió por orden de Salomón.', 'Publicado básico'),
('glo-joacim-eliaquim-hijo-josias', 'Joacim / Eliaquim (hijo de Josías; rey de Judá)', 'joacim-eliaquim-hijo-josias', 'Joacim, originalmente llamado Eliaquim, fue hijo del rey Josías y gobernó Judá durante once años. El faraón Necao lo colocó en el trono y cambió su nombre a Joacim; su reinado quedó marcado primero por la subordinación a Egipto y luego por el dominio babilónico de Nabucodonosor, frente al cual terminó rebelándose. Los libros de Reyes, Crónicas y Jeremías lo presentan negativamente, y Jeremías 36 relata que cortó y quemó el rollo profético leído ante él.', 'Publicado básico');
